// Sentientia LMS PWA — install_prompt — Phase D.1.b.
//
// IMPORTANT: This file is HAND-BUILT ES5 with a NAMED DEFINE.
// See subscribe.min.js for the AMD-pipeline lesson learned 2026-05-20.
//
// Captures beforeinstallprompt → reveals .sentientia-install-cta →
// click triggers prompt → logs outcome to localStorage to avoid
// nagging dismissed users for 7 days.
define('local_sentientia_pwa/install_prompt', [], function() {
    'use strict';

    // Match only the OUTER alert (.sentientia-install-cta) — Phase D.1.b
    // 2026-05-21 had this match the inner buttons too, which caused
    // closest() ambiguity. Buttons use data-action="install|dismiss"
    // and we walk closest from there.
    var ALERT_SELECTOR  = '.sentientia-install-cta';
    var BUTTON_SELECTOR = '.sentientia-install-cta-action';
    var STORAGE_KEY     = 'sentientia_install_dismissed';

    function isQuarantined() {
        var dismissedAt = window.localStorage.getItem(STORAGE_KEY);
        if (!dismissedAt) { return false; }
        var ageDays = (Date.now() - parseInt(dismissedAt, 10)) / 86400000;
        return ageDays < 7;
    }

    function showCta() {
        var ctas = document.querySelectorAll(ALERT_SELECTOR);
        for (var i = 0; i < ctas.length; i++) {
            ctas[i].removeAttribute('hidden');
            ctas[i].classList.remove('d-none');
        }
    }

    function hideCta() {
        var ctas = document.querySelectorAll(ALERT_SELECTOR);
        for (var i = 0; i < ctas.length; i++) {
            ctas[i].setAttribute('hidden', 'hidden');
            ctas[i].classList.add('d-none');
        }
    }

    function markDismissed() {
        try { window.localStorage.setItem(STORAGE_KEY, String(Date.now())); }
        catch (e) { /* private mode — silent */ }

        // Belt-and-braces: also POST to the server so the user prefs
        // record persists across browsers + suppresses the SERVER-side
        // render on the next request. Fire-and-forget — UI doesn't wait.
        try {
            var url = (typeof M !== 'undefined' && M.cfg && M.cfg.wwwroot)
                ? (M.cfg.wwwroot + '/local/sentientia_pwa/dismiss_install.php')
                : '/local/sentientia_pwa/dismiss_install.php';
            var sesskey = (typeof M !== 'undefined' && M.cfg && M.cfg.sesskey)
                ? M.cfg.sesskey : '';
            if (sesskey && window.fetch) {
                window.fetch(url, {
                    method: 'POST',
                    credentials: 'same-origin',
                    headers: {'Content-Type': 'application/x-www-form-urlencoded'},
                    body: 'sesskey=' + encodeURIComponent(sesskey)
                });
            }
        } catch (e) { /* silent */ }
    }

    function init() {
        var deferredPrompt = null;
        var quarantined = isQuarantined();

        // ALWAYS register beforeinstallprompt + preventDefault so Chrome's
        // NATIVE install banner is suppressed regardless of quarantine.
        // Only reveal OUR custom CTA when not quarantined. (Phase D.1.b
        // bug fix 2026-05-22 — without the always-preventDefault, Chrome's
        // native mini-info bar kept reappearing on every page load even
        // after the user clicked Not now.)
        window.addEventListener('beforeinstallprompt', function(ev) {
            ev.preventDefault();
            deferredPrompt = ev;
            if (!quarantined) {
                showCta();
            }
        });

        window.addEventListener('appinstalled', function() {
            markDismissed();
            hideCta();
        });

        document.addEventListener('click', function(ev) {
            // closest() walks ev.target up to find a matching ancestor.
            // We bind to the button-specific class so we never resolve
            // to the wrapper alert itself.
            var btn = ev.target.closest(BUTTON_SELECTOR);
            if (!btn) { return; }
            ev.preventDefault();

            if (btn.dataset.action === 'dismiss') {
                markDismissed();
                hideCta();
                return;
            }

            // Install button — must have a stashed prompt to fire.
            if (!deferredPrompt) {
                // No stashed prompt yet (e.g. user clicked Install before
                // Chrome decided we were installable). Hide the CTA so
                // the user isn't stuck on a non-functional button.
                hideCta();
                return;
            }
            deferredPrompt.prompt();
            deferredPrompt.userChoice.then(function(choice) {
                if (choice.outcome === 'dismissed') {
                    markDismissed();
                }
                deferredPrompt = null;
                hideCta();
            });
        });
    }

    return {
        init: init
    };
});
